from cardio_1 import a, G
# Abréviations nouvelles du cours I97 (troubles circulatoires après un acte médical) ; aucune clé nouvelle n’est nécessaire à ce stade.
a('Schulz-Menger',[('Schulz-Menger','nom propre : Jeanette Schulz-Menger, cardiologue, présidente du groupe de rédaction')],'Jeanette Schulz-Menger (nom d’auteur)','<p>Cardiologue allemande, spécialiste de l’IRM cardiaque, présidente du groupe de rédaction des recommandations ESC 2025 des myocardites et péricardites.</p>')
a('CardioNetworks',[('CardioNetworks','nom propre d’une fondation néerlandaise, non une abréviation')],'CardioNetworks, fondation éditrice de ressources cardiologiques libres','<p>Fondation néerlandaise qui publie sous licence libre des ressources d’enseignement en cardiologie, dont l’atlas d’échocardiographie ECHOpedia.</p>')
a('ECHOpedia',[('ECHOpedia','nom propre : contraction de « echo » et « encyclopedia », atlas d’échocardiographie')],'ECHOpedia, atlas libre d’échocardiographie','<p>Atlas en ligne d’échocardiographie publié par CardioNetworks sous licence Creative Commons Attribution – Partage dans les mêmes conditions ; source de la figure du flux mitral de ce cours.</p>')
a('AMC',[('A','Academisch'),('M','Medisch'),('C','Centrum')],'Academisch Medisch Centrum (centre médical universitaire d’Amsterdam)','<p>Centre hospitalier universitaire d’Amsterdam, aujourd’hui intégré à Amsterdam UMC ; son laboratoire d’échocardiographie a fourni l’enregistrement Doppler de ce cours.</p>')
